def solve(gi):
    h,w=len(gi),len(gi[0])
    O=[row[:] for row in gi]
    # detect vertical/horizontal lines (>=2/3 fraction of 2s)
    Hv=[r for r in range(h) if sum(x==2 for x in gi[r])>=2*w//3]
    Vt=[c for c in range(w) if sum(gi[r][c]==2 for r in range(h))>=2*h//3]
    boxes=[]
    seen=set()
    for r in range(h):
        for c in range(w):
            if gi[r][c]==3 and (r,c) not in seen:
                comp={(r,c)};seen.add((r,c))
                q=[(r,c)]
                while q:
                    y,x=q.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and gi[ny][nx]==3 and (ny,nx) not in seen:
                            seen.add((ny,nx));q.append((ny,nx));comp.add((ny,nx))
                rs=[p[0] for p in comp];cs_=[p[1] for p in comp]
                if min(rs)==max(rs)+2 and len(comp)==8:  # 3x3 ring
                    boxes.append((min(rs)+1,min(cs_)+1,max(rs),max(cs_)))  # bbox inclusive
    def paint_line(row_or_col, axis):
        cells=[]
        if axis=='h':
            for c in range(w):
                if gi[row_or_col][c]==0: cells.append((row_or_col,c))
        else:
            for r in range(h):
                if gi[r][row_or_col]==0: cells.append((r,row_or_col))
        for r,c in cells: O[r][c]=1
    def stamp(centerR,targetL):
        # ring of 1s around center (centerR, targetL), bbox rows centerR-1..centerR+1, cols targetL-1..targetL+1
        for rr in range(centerR-1,centerR+2):
            for cc in range(targetL-1,targetL+2):
                if (rr,cc)!=(centerR,targetL) and 0<=rr<h and 0<=cc<w: O[rr][cc]=1
    for (r0,c0,r1,c1) in boxes:
        cr=(r0+r1)//2; cc=(c0+c1)//2
        # center row bar
        paint_line(cr,'h')
        # center col bar
        paint_line(cc,'v')
        # stamp on target line
        other=None
        if Vt:
            mine=[l for l in Vt if l==cc]
            others=Vt
            if mine: others=[l for l in others if l!=cc]
        elif Hv:
            other=[l for l in Hv if l!=cr]
        if other:
            # reverse-index among lines containing the box
            Lines=others+[mine] if mine else others
            idx=Lines.index(min(Lines,key=lambda l:(min(l),l)) if False else None)
            # pick mine's index among sorted all lines
            All=Lv=[min(Vt,key=lambda l:l)] if Vt else Hv
            idxAll=Vt.index(cc) if Vt else Hv.index(cr)
            tgt=sorted([l for l in All if l not in mine]+mine)[len(All)-1-idxAll] if others else others[0]
            stamp(cr,tgt)
    return O
